def test_conversion_rate_includes_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_duplicate_then_sorts():
    events = parse_session_log(["a,3,1", "b,2,1", "a,2,0", "z,1,"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_parse_whitespace_comments_and_flags():
    lines = ["", " \t", " # comment", " x , 4 , 0 ", " y , 5 , "]
    assert parse_session_log(lines) == [
        {"id": "x", "day": 4, "converted": False},
        {"id": "y", "day": 5, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,0,1", "x,today,1"])
def test_parse_errors_count_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["", "x,1,1", " # comment", bad])


def test_daily_counts_and_window_boundaries():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    counts = daily_conversion_counts(events, 1, 4)
    assert counts == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 3, 2) == []
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 2) == 0
    assert conversions_in_window(counts, 10) == 2


def test_summary_pools_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,1,1", "c,4,0"]), "c": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_ties_and_empty_groups():
    groups = {"z": [{"converted": False}], "m": [{"converted": True}], "b": [], "a": [{"converted": True}]}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "m", "z"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("m", 1.0), ("z", 0.0)]


def test_streak_counts_only_consecutive_positive_entries():
    assert longest_conversion_streak([2, -1, 1, 1, 0, 4]) == 2
    assert longest_conversion_streak([]) == 0
